        return 0 if v == 0 else (1 if v > 0 else -1)

    def is_pair(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2

    def pos(v):
        if is_pair(v):
            return (v[0], v[1])
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def step_away(a, b):
        return [clamp(a[0] - b[0]), clamp(a[1] - b[1])]

    def best_item(items, src, want_max=False):
        best = None
        best_d = None
        for it in items or []:
            p = pos(it)
            if p is None:
                continue
            d = manhattan(src, p)
            if best is None or ((d > best_d) if want_max else (d < best_d)):
                best = p
                best_d = d
        return best, best_d

    def bounded(p, w, h):
        x, y = p
        if w:
            x = 0 if x < 0 else (w - 1 if x >= w else x)
        if h:
            y = 0 if y < 0 else (h - 1 if y >= h else y)
        return (x, y)

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
