                    s += 3
                else:
                    s -= 4
            else:
                if w and h:
                    center = (w // 2, h // 2)
                    s += max(0, 10 - manhattan(np, center))
                else:
                    s += 0

            # Deny nearby resources to opponent if possible.
            if resources:
                near_opp, d1 = best_item(resources, opp_pos)
